const data = msg.payload;
if (!data || !data.vaga_id) {
    return [null, null];
}

const ocupada = data.ocupada === true;

const updateMsg = { payload: data, params: [ocupada, data.vaga_id] };
const insertMsg = { payload: data, params: [data.vaga_id, ocupada] };

return [updateMsg, insertMsg];

const rows = msg.payload || [];
const total = rows.length;
const ocupadas = rows.filter(r => r.ocupada).length;
const livres = total - ocupadas;
const taxa = total ? Math.round((ocupadas / total) * 1000) / 10 : 0;

const porAndar = {};
rows.forEach(r => {
    porAndar[r.andar] = porAndar[r.andar] || { total: 0, ocupadas: 0, livres: 0 };
    porAndar[r.andar].total++;
    if (r.ocupada) porAndar[r.andar].ocupadas++; else porAndar[r.andar].livres++;
});

const resumo = {
    livres, ocupadas, total,
    taxa_ocupacao: taxa,
    por_andar: porAndar,
    atualizado_em: new Date().toISOString()
};

const preferenciaisOcupadas = rows.filter(r => r.preferencial && r.ocupada).map(r => r.id);

let alerta = null;
if (total > 0 && livres === 0) {
    alerta = { nivel: "critico", mensagem: "LOTADO", timestamp: new Date().toISOString() };
} else if (preferenciaisOcupadas.length > 0) {
    alerta = { nivel: "atencao", mensagem: "Alerta: Vaga PCD ocupada sem autorização!", vagas: preferenciaisOcupadas, timestamp: new Date().toISOString() };
}

// Um tópico retido por vaga (para cards individuais em apps como IoT MQTT Panel)
const porVagaMsgs = rows.map(r => {
    const estado = !r.ocupada ? "LIVRE" : (r.preferencial ? "OCUPADA_PCD" : "OCUPADA");
    return { topic: `estacionamento/vagas/${r.id}/status`, payload: estado, qos: 1, retain: true };
});

return [{ payload: resumo }, alerta ? { payload: alerta } : null, porVagaMsgs];

const data = msg.payload;
if (!data || !data.vaga_id) {
    return [null, null];
}

// Cenário 1 = Node-RED (simulador de backup) · Cenário 2 = Wokwi (ESP32 físico)
const origem = data.origem === "simulador" ? "simulador" : "wokwi";
const ocupada = data.ocupada === true;
const vagasTable = "vagas_" + origem;
const histTable = "historico_" + origem;

const updateMsg = {
    query: `UPDATE ${vagasTable} SET ocupada = $1, atualizado_em = NOW() WHERE id = $2`,
    params: [ocupada, data.vaga_id],
    origem
};
const insertMsg = {
    query: `INSERT INTO ${histTable} (vaga_id, ocupada) VALUES ($1, $2)`,
    params: [data.vaga_id, ocupada],
    origem
};

return [updateMsg, insertMsg];

delete msg.params;
msg.query = `SELECT id, andar, preferencial, ocupada FROM vagas_${msg.origem} ORDER BY id ASC`;
return msg;

